// Generated by `dokimos verification scaffold` from plan VP-B1-APPROVAL. Each body fails until
// it is written; `dokimos verification coverage` reports DOKIMOS-UNIMPLEMENTED as a placeholder.
import { test, expect } from "@playwright/test";

const ALL_COMMANDS = ["Submit", "Approve", "Reject", "Revise"];

// Creates a request through the real UI and returns its page path (/requests/{id}).
async function createRequest(page, title) {
  await page.goto("/");
  await page.locator("form[data-testid=create] input[name=title]").fill(title);
  await Promise.all([
    page.waitForURL(/\/requests\/[0-9a-fA-F]{32}$/),
    page.locator("form[data-testid=create] [data-testid=create-submit]").click()
  ]);
  await expect(page.getByTestId("title")).toHaveText(title);
  await expect(page.getByTestId("state")).toHaveText("Draft");
  await expect(page.getByTestId("version")).toHaveText("0");
  return new URL(page.url()).pathname;
}

async function runCommand(page, command, note) {
  const form = page.locator("form[data-testid=command-form]");
  if (note !== undefined) await form.locator("input[name=note]").fill(note);
  // Wait for the command POST and the page it leads to, so later assertions see the new page.
  await Promise.all([
    page.waitForResponse((r) => r.request().method() === "POST" && r.url().endsWith("/command")),
    form.locator(`button[name=command][value=${command}][data-testid=cmd-${command}]`).click()
  ]);
  await page.waitForLoadState("load");
}

// Asserts that exactly the given commands are offered as buttons, and the note input only when needed.
async function expectOffered(page, legal) {
  const form = page.locator("form[data-testid=command-form]");
  for (const c of ALL_COMMANDS) {
    await expect(page.getByTestId(`cmd-${c}`)).toHaveCount(legal.includes(c) ? 1 : 0);
  }
  await expect(page.locator("button[name=command]")).toHaveCount(legal.length);
  const needsNote = legal.includes("Approve") || legal.includes("Reject");
  await expect(form.locator("input[name=note]")).toHaveCount(needsNote ? 1 : 0);
}

test("APR-005-O1", async ({ page }) => {
  // APR-005-O1: in a real browser, create a request, submit it and approve it with a note. After a full page reload, the page shows state `Approved` and the note.
  const note = `Approved for Q3 – Größe ok ${Date.now()}`;
  const path = await createRequest(page, "Browser workflow O1");

  await runCommand(page, "Submit");
  await expect(page.getByTestId("state")).toHaveText("Submitted");
  await expect(page.getByTestId("version")).toHaveText("1");

  await runCommand(page, "Approve", note);
  await expect(page.getByTestId("state")).toHaveText("Approved");

  await page.reload();
  expect(new URL(page.url()).pathname).toBe(path);
  await expect(page.getByTestId("state")).toHaveText("Approved");
  await expect(page.getByTestId("note")).toHaveText(note);
  await expect(page.getByTestId("version")).toHaveText("2");

  // A completely fresh navigation shows the same persisted outcome.
  await page.goto(path);
  await expect(page.getByTestId("state")).toHaveText("Approved");
  await expect(page.getByTestId("note")).toHaveText(note);
});

test("APR-005-O2", async ({ page }) => {
  // APR-005-O2: the page offers only the commands that are legal in the request's current state. In `Draft` there is no Approve button; in `Approved` there is no command button at all.
  await createRequest(page, "Browser workflow O2 approve path");
  await expectOffered(page, ["Submit"]);
  await expect(page.getByTestId("cmd-Approve")).toHaveCount(0);

  await runCommand(page, "Submit");
  await expect(page.getByTestId("state")).toHaveText("Submitted");
  await expectOffered(page, ["Approve", "Reject"]);

  await runCommand(page, "Approve", "fine");
  await expect(page.getByTestId("state")).toHaveText("Approved");
  await expectOffered(page, []);
  await page.reload();
  await expect(page.getByTestId("state")).toHaveText("Approved");
  await expect(page.locator("button[name=command]")).toHaveCount(0);

  // The reject path: Rejected offers only Revise, which leads back to Draft.
  await createRequest(page, "Browser workflow O2 reject path");
  await runCommand(page, "Submit");
  await runCommand(page, "Reject", "too expensive");
  await expect(page.getByTestId("state")).toHaveText("Rejected");
  await expectOffered(page, ["Revise"]);

  await runCommand(page, "Revise");
  await expect(page.getByTestId("state")).toHaveText("Draft");
  await expectOffered(page, ["Submit"]);
});

test("APR-005-O3", async ({ page }) => {
  // APR-005-O3: two tabs open the same request, and the first tab submits it. When the second tab then submits, the page reports a conflict, and after reload the request is still exactly once `Submitted` at version 1.
  const path = await createRequest(page, "Browser workflow O3");
  const second = await page.context().newPage();
  await second.goto(path);
  await expect(second.getByTestId("state")).toHaveText("Draft");
  await expect(second.getByTestId("version")).toHaveText("0");

  await runCommand(page, "Submit");
  await expect(page.getByTestId("state")).toHaveText("Submitted");
  await expect(page.getByTestId("version")).toHaveText("1");

  // The second tab still shows the Draft page rendered at version 0; submitting from it must conflict.
  const [response] = await Promise.all([
    second.waitForResponse((r) => r.request().method() === "POST" && r.url().endsWith(`${path}/command`)),
    second.getByTestId("cmd-Submit").click()
  ]);
  expect(response.status()).toBe(409);
  await expect(second.getByTestId("conflict")).toBeVisible();

  // Reload (fresh GET, not a form re-post) in both tabs: exactly one submission took effect.
  for (const tab of [second, page]) {
    await tab.goto(path);
    await expect(tab.getByTestId("state")).toHaveText("Submitted");
    await expect(tab.getByTestId("version")).toHaveText("1");
    await expect(tab.getByTestId("conflict")).toHaveCount(0);
  }
  await second.close();
});
